<style>
:root{--xd3-ink:#242321;--xd3-yellow:#ffc42b;--xd3-orange:#ef4c23;--xd3-muted:#6d6b65;--xd3-line:#e6e2d9;--xd3-container:min(1180px,calc(100% - 48px))}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#fffefa;color:var(--xd3-ink);font-family:Arial,Helvetica,sans-serif;line-height:1.55}a{color:inherit;text-decoration:none}button,input{font:inherit}.xd3-container{width:var(--xd3-container);margin:auto}.xd3-header{position:relative;z-index:5;background:#fff}.xd3-contact-row{display:grid;grid-template-columns:minmax(220px,1.2fr) repeat(3,minmax(150px,1fr)) auto;gap:18px;align-items:center;min-height:104px}.xd3-logo{display:flex;align-items:center;gap:11px;font-size:22px;font-weight:700}.xd3-logo img{display:block;max-width:250px;max-height:78px;object-fit:contain}.xd3-logo__mark{display:grid;width:42px;height:42px;place-items:center;background:var(--xd3-yellow);font-size:13px;font-weight:900}.xd3-contact-item{display:grid;gap:2px;color:var(--xd3-muted);font-size:13px}.xd3-contact-item b{color:var(--xd3-ink);font-size:14px;text-transform:uppercase}.xd3-auth-actions{display:flex;gap:7px}.xd3-auth-actions button,.xd3-mobile-auth button{min-height:32px;padding:0 10px;border:1px solid var(--xd3-ink);border-radius:2px;background:#fff;font-weight:700;cursor:pointer}.xd3-auth-actions button:last-child,.xd3-mobile-auth button:last-child{border-color:var(--xd3-orange);background:var(--xd3-orange);color:#fff}.xd3-nav-wrap{position:relative;z-index:2;margin-bottom:-34px}.xd3-nav-shell{display:grid;grid-template-columns:1fr 250px;min-height:70px;background:var(--xd3-yellow);box-shadow:0 16px 30px rgba(32,32,31,.12)}.xd3-nav{display:flex;align-items:center;justify-content:space-around;gap:14px;padding:0 16px;font-weight:700}.xd3-nav a{display:inline-flex;align-items:center;white-space:nowrap}.xd3-nav a.has-children:after{width:6px;height:6px;margin:-4px 0 0 8px;border-right:2px solid currentColor;border-bottom:2px solid currentColor;content:"";transform:rotate(45deg)}.xd3-search{display:grid;grid-template-columns:1fr 52px;margin:11px;background:#fff}.xd3-search input{min-width:0;border:0;padding:0 14px;outline:0}.xd3-search button{border:0;border-left:1px solid var(--xd3-line);background:#fff;font-size:20px;cursor:pointer}.xd3-menu-toggle,.xd3-mobile-auth{display:none}.xd3-hero{position:relative;min-height:620px;overflow:hidden;background:#e8e3d8}.xd3-hero__slide{position:absolute;inset:0;opacity:0;transition:opacity .45s}.xd3-hero__slide.is-active{opacity:1}.xd3-hero__slide img{width:100%;height:100%;object-fit:cover}.xd3-hero__slide:after{position:absolute;inset:0;background:linear-gradient(90deg,rgba(255,254,250,.96) 0%,rgba(255,254,250,.7) 41%,rgba(255,254,250,.08) 73%);content:""}.xd3-hero__content{position:relative;z-index:1;display:flex;align-items:center;min-height:620px}.xd3-hero__copy{max-width:580px;padding-top:64px}.xd3-kicker{margin:0 0 10px;color:var(--xd3-orange);font-size:14px;font-weight:700;text-transform:uppercase}.xd3-hero h1{margin:0 0 20px;font-size:clamp(42px,5vw,64px);font-weight:400;line-height:1.08}.xd3-hero p{margin:0;color:#494741;font-size:18px}.xd3-hero__highlights{display:flex;gap:12px;margin-top:32px}.xd3-hero__highlights span{display:grid;min-width:145px;min-height:104px;place-items:center;padding:12px;background:#fffc;color:var(--xd3-ink);font-size:12px;font-weight:700;text-align:center;text-transform:uppercase}.xd3-hero__highlights b{display:block;margin-bottom:7px;color:var(--xd3-orange);font-size:24px}.xd3-hero__arrow{position:absolute;z-index:2;top:54%;display:grid;width:52px;height:52px;place-items:center;border:0;border-radius:50%;background:#242321dd;color:#fff;font-size:32px;cursor:pointer}.xd3-hero__arrow--prev{left:28px}.xd3-hero__arrow--next{right:28px}.xd3-hotline{padding:84px 0;background:var(--xd3-yellow);text-align:center}.xd3-hotline p{margin:0;font-size:21px}.xd3-hotline__icon{display:grid;width:96px;height:96px;place-items:center;margin:18px auto 8px;border:5px solid var(--xd3-ink);border-radius:50%;font-size:44px}.xd3-hotline strong{display:block;font-size:clamp(52px,7vw,90px);letter-spacing:2px;line-height:1}.xd3-hotline__note{margin-top:16px!important;color:#4d431d}.xd3-section{padding:100px 0;background:#fff}.xd3-section__head{display:flex;align-items:end;justify-content:space-between;gap:30px;margin-bottom:42px}.xd3-section h2{margin:0;font-size:38px;line-height:1.17}.xd3-source-note{max-width:350px;margin:0;color:var(--xd3-muted);font-size:14px;text-align:right}.xd3-source-note strong{color:var(--xd3-orange)}.xd3-content-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.xd3-content-card{overflow:hidden;border:1px solid var(--xd3-line);background:#fff;transition:.2s}.xd3-content-card:hover{transform:translateY(-5px);box-shadow:0 16px 32px rgba(32,32,31,.12)}.xd3-content-card img{display:block;width:100%;height:245px;object-fit:cover}.xd3-content-card__body{padding:24px}.xd3-content-card small{color:var(--xd3-orange);font-weight:700;text-transform:uppercase}.xd3-content-card h3{margin:8px 0;font-size:22px;line-height:1.3}.xd3-content-card p{margin:0;color:var(--xd3-muted)}.xd3-content-card__body a{display:inline-flex;margin-top:17px;font-size:14px;font-weight:700}.xd3-process{padding:100px 0 112px;background:#fffefa;text-align:center}.xd3-process__title{position:relative;display:inline-block;min-width:min(670px,100%);margin-bottom:16px;padding:24px 72px 20px;border:1px solid var(--xd3-yellow)}.xd3-process__title:before{position:absolute;top:-15px;left:50%;width:28px;height:28px;border:8px solid #fffefa;background:var(--xd3-yellow);content:"";transform:translateX(-50%) rotate(45deg)}.xd3-process__title h2{margin:0;font-size:36px;font-weight:400}.xd3-process__title p{margin:8px 0 0;color:var(--xd3-orange);font-size:14px;font-weight:700;text-transform:uppercase}.xd3-process__intro{max-width:760px;margin:0 auto 50px;color:var(--xd3-muted);font-size:17px}.xd3-steps{display:grid;grid-template-columns:repeat(4,1fr);gap:22px}.xd3-step{position:relative}.xd3-step:not(:last-child):after{position:absolute;top:67px;left:calc(50% + 74px);width:calc(100% - 126px);height:2px;background:var(--xd3-yellow);content:""}.xd3-step__number{display:grid;width:138px;height:138px;place-items:center;margin:0 auto 20px;border:5px solid var(--xd3-yellow);border-radius:50%;background:#fff;font-size:33px;font-weight:700}.xd3-step h3{margin:0 0 9px;font-size:18px}.xd3-step p{max-width:240px;margin:0 auto;color:var(--xd3-muted);font-size:14px}.xd3-partners{padding:76px 0;background:#fff}.xd3-partner-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:24px;align-items:center}.xd3-partner{display:grid;min-height:116px;place-items:center;padding:16px;text-align:center}.xd3-partner img{max-width:180px;max-height:84px;object-fit:contain}.xd3-partner strong{font-size:20px}.xd3-footer{padding:64px 0 0;background:#292927;color:#fff}.xd3-footer__grid{display:grid;grid-template-columns:1.25fr .9fr 1fr;gap:70px;padding-bottom:46px}.xd3-footer .xd3-logo{color:#fff}.xd3-footer h3{margin:0 0 18px;color:var(--xd3-yellow);font-size:17px}.xd3-footer p,.xd3-footer li,.xd3-footer a{color:#ffffffb8;font-size:14px}.xd3-footer ul{display:grid;gap:9px;margin:0;padding:0;list-style:none}.xd3-footer li:before{margin-right:8px;color:var(--xd3-yellow);content:"›";font-size:18px}.xd3-footer__bottom{padding:18px;border-top:1px solid #ffffff20;color:#ffffff90;font-size:13px;text-align:center}.xd-edit-block{position:absolute;z-index:10;right:16px;top:16px;padding:8px 12px;border:0;border-radius:3px;background:var(--xd3-orange);color:#fff;font-weight:700;cursor:pointer}@media(max-width:980px){.xd3-contact-row{grid-template-columns:repeat(2,1fr);padding:20px 0}.xd3-logo{grid-column:span 2}.xd3-nav-shell{grid-template-columns:1fr}.xd3-search{display:none}.xd3-content-grid,.xd3-steps{grid-template-columns:repeat(2,1fr)}.xd3-step:nth-child(2):after{display:none}.xd3-partner-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){:root{--xd3-container:min(100% - 30px,1180px)}.xd3-contact-row{display:flex;flex-wrap:wrap;gap:14px;min-height:0}.xd3-logo{width:100%}.xd3-contact-item{font-size:12px}.xd3-auth-actions{margin-left:auto}.xd3-nav-wrap{margin-bottom:0}.xd3-nav-shell{display:block;min-height:58px}.xd3-menu-toggle{display:block;width:100%;min-height:58px;border:0;background:var(--xd3-yellow);font-weight:700;text-align:left;padding:0 16px}.xd3-nav{display:none;gap:0;padding:10px 16px;background:#fff;box-shadow:0 16px 30px rgba(32,32,31,.13)}.xd3-nav.is-open{display:grid}.xd3-nav a{padding:10px 0;border-bottom:1px solid var(--xd3-line)}.xd3-mobile-auth{display:flex;gap:8px;padding-top:12px}.xd3-hero,.xd3-hero__content{min-height:555px}.xd3-hero__slide:after{background:linear-gradient(90deg,rgba(255,254,250,.95),rgba(255,254,250,.62))}.xd3-hero__copy{padding-top:20px}.xd3-hero h1{font-size:40px}.xd3-hero p{font-size:16px}.xd3-hero__highlights{gap:8px}.xd3-hero__highlights span{min-width:0;min-height:88px;flex:1;font-size:10px}.xd3-hero__arrow{display:none}.xd3-hotline{padding:65px 0}.xd3-hotline p{font-size:17px}.xd3-section,.xd3-process{padding:70px 0}.xd3-section__head{display:block}.xd3-section h2{font-size:31px}.xd3-source-note{margin-top:14px;text-align:left}.xd3-content-grid,.xd3-steps,.xd3-partner-grid,.xd3-footer__grid{grid-template-columns:1fr}.xd3-step:not(:last-child):after{display:none}.xd3-process__title{min-width:0;width:100%;padding:25px 16px 20px}.xd3-process__title h2{font-size:29px}.xd3-partners{padding:56px 0}.xd3-footer__grid{gap:34px}}
</style>
